#pragma once
void testGlslTranslation(){
    using namespace bridge;using namespace bridge::shaderloader;
    const auto fails=[](auto fn){try{fn();}catch(const std::exception&){return true;}return false;};
    const auto write=[](const char* name,const std::string& text){std::ofstream out(std::string("outputs/native-renderer-verification/")+name,std::ios::binary);requireCPU(bool(out),"Cannot write translation fixture.");out.write(text.data(),static_cast<std::streamsize>(text.size()));requireCPU(bool(out),"Truncated translation fixture.");};
    const auto prep=[](std::string body){auto files=PackSources::create({{"source.fsh","#version 120\n"+body}});return preparePackShader(*files,"source.fsh",{}).glsl;};
    const auto fragment=[&](std::string body){return GlslTranslation::translate(prep(std::move(body)),PackShaderStage::Fragment);};
    std::ifstream input("outputs/native-renderer-verification/translation-source-fixture.bin",std::ios::binary);requireCPU(bool(input),"Missing ZIP/directory translation snapshot.");const std::vector<uint8_t> bytes(std::istreambuf_iterator<char>(input),{});const auto files=PackSources::decode(bytes);
    const auto color=GlslTranslation::preparePair(*files,"legacy.vsh","legacy.fsh",{{"MRT","0"}}),mrt=GlslTranslation::preparePair(*files,"legacy.vsh","legacy.fsh",{{"MRT","1"}});
    requireCPU(color.vertex.attributes==std::vector<ShaderVariable>{{"position","vec3"},{"coord","vec2"}}&&color.vertex.varyings==std::vector<ShaderVariable>{{"uv","vec2"}}&&color.fragment.varyings==color.vertex.varyings,"Translation lost explicit interface names/types.");
    requireCPU(color.vertex.uniforms==std::vector<ShaderVariable>{{"transform","mat4"}}&&color.fragment.uniforms==std::vector<ShaderVariable>{{"sourceTex","sampler2D"}},"Translation invented uniform binding semantics.");
    requireCPU(color.fragment.outputLocations==std::vector<uint32_t>{0}&&mrt.fragment.outputLocations==std::vector<uint32_t>{0,2},"Fragment output locations were densified or assigned as texture IDs.");
    requireCPU(color.fragment.textureCalls==1&&color.fragment.sourceVersion==120&&color.fragment.targetVersion==330&&color.fragment.text.starts_with("#version 330 core\n"),"Translation did not produce explicit core GLSL.");
    requireCPU(color.vertex.text.find("in vec3 position")!=std::string::npos&&color.vertex.text.find("out vec2 uv")!=std::string::npos&&color.fragment.text.find("in vec2 uv")!=std::string::npos,"Stage-dependent attribute/varying conversion failed.");
    requireCPU(mrt.fragment.text.find("layout(location=2) out vec4 bloxdy_legacy_out2;")!=std::string::npos&&mrt.fragment.text.find("gl_FragData")==std::string::npos&&mrt.fragment.text.find("texture (")!=std::string::npos,"Legacy output or texture call translation failed.");
    write("pack-translation-color.vert",color.vertex.text);write("pack-translation-color.frag",color.fragment.text);write("pack-translation-mrt.vert",mrt.vertex.text);write("pack-translation-mrt.frag",mrt.fragment.text);
    // Compile both the original prepared legacy sources and translated pairs.
    for(const bool multi:{false,true}){const auto suffix=multi?"mrt":"color";const auto v=preparePackShader(*files,"legacy.vsh",{{"MRT",multi?"1":"0"}}),f=preparePackShader(*files,"legacy.fsh",{{"MRT",multi?"1":"0"}});write((std::string("pack-legacy-")+suffix+".vert").c_str(),v.glsl.text);write((std::string("pack-legacy-")+suffix+".frag").c_str(),f.glsl.text);requireCPU(f.glsl.sourcePaths==(multi?mrt:color).fragment.sourcePaths,"Translation changed source map identity.");}
    const auto bad=GlslTranslation::preparePair(*files,"legacy.vsh","negative.fsh",{});requireCPU(bad.fragment.sourcePaths[1]=="lib/bad.glsl","Translation negative file map changed.");write("pack-translation-negative.frag",bad.fragment.text);
    const auto data=fragment("void main(){gl_FragData[7]=vec4(1.0);gl_FragData[7].a=0.5;}\n");requireCPU(data.outputLocations==std::vector<uint32_t>{7},"Repeated sparse output uses created duplicate/reindexed declarations.");
    const auto version=fragment("const int originalVersion=__VERSION__;\nvoid main(){gl_FragColor=vec4(float(originalVersion));}\n");requireCPU(version.text.find("originalVersion = 120")!=std::string::npos,"Translation re-evaluated source macros using target GLSL version.");
    const auto shadows=fragment("float my_gl_FragColorSuffix(float x){return x;}\nvoid main(){gl_FragColor=vec4(my_gl_FragColorSuffix(1.0));}\n");requireCPU(shadows.text.find("my_gl_FragColorSuffix")!=std::string::npos,"Translation renamed identifier substrings.");
    const auto vertexLod=GlslTranslation::translate(prep("attribute vec3 position;\nuniform sampler2D tex;\nvoid main(){gl_Position=vec4(position,1.0)+texture2DLod(tex,vec2(0.5),0.0);}\n"),PackShaderStage::Vertex);requireCPU(vertexLod.text.find("textureLod")!=std::string::npos&&vertexLod.textureCalls==1,"Vertex LOD call was not translated.");
    const auto calls=PackSources::create({{"calls.vsh","#version 120\n#extension GL_ARB_shader_texture_lod : require\nattribute vec3 position;\nuniform sampler2D tex2;\nuniform sampler3D tex3;\nvarying vec4 shade;\nvoid main(){shade=texture2D(tex2,vec2(0.2))+texture3D(tex3,vec3(0.2))+texture2DProj(tex2,vec3(0.2,0.3,1.0))+texture3DProj(tex3,vec4(0.2,0.3,0.4,1.0))+texture2DLod(tex2,vec2(0.2),0.0)+texture3DLod(tex3,vec3(0.2),0.0);gl_Position=vec4(position,1.0);}"},{"calls.fsh","#version 120\nvarying vec4 shade;\nvoid main(){gl_FragColor=shade;}"}});
    const auto allCalls=GlslTranslation::preparePair(*calls,"calls.vsh","calls.fsh",{});requireCPU(allCalls.vertex.textureCalls==6&&allCalls.vertex.requestedExtensions.size()==1&&allCalls.vertex.requestedExtensions[0].name=="GL_ARB_shader_texture_lod","Not all six supported texture call variants were translated.");
    write("pack-translation-textures.vert",allCalls.vertex.text);write("pack-translation-textures.frag",allCalls.fragment.text);write("pack-legacy-textures.vert",preparePackShader(*calls,"calls.vsh",{}).glsl.text);write("pack-legacy-textures.frag",preparePackShader(*calls,"calls.fsh",{}).glsl.text);
    const auto proto=fragment("vec4 helper(vec4 c);\nvec4 helper(vec4 c){return c;}\nvoid main(){gl_FragColor=helper(vec4(1.0));}\n");requireCPU(proto.outputLocations==std::vector<uint32_t>{0},"Ordinary prototypes or typed helper functions failed.");
    const auto missing=PackSources::create({{"v.vsh","#version 120\nvoid main(){gl_Position=vec4(0.0);}"},{"f.fsh","#version 120\nvarying vec2 uv;\nvoid main(){gl_FragColor=vec4(uv,0.0,1.0);}"}});requireCPU(fails([&]{GlslTranslation::preparePair(*missing,"v.vsh","f.fsh",{});}),"Missing pair varying was accepted.");
    const auto conflict=PackSources::create({{"v.vsh","#version 120\nuniform vec4 value;\nvoid main(){gl_Position=value;}"},{"f.fsh","#version 120\nuniform vec3 value;\nvoid main(){gl_FragColor=vec4(value,1.0);}"}});requireCPU(fails([&]{GlslTranslation::preparePair(*conflict,"v.vsh","f.fsh",{});}),"Conflicting cross-stage uniform was accepted.");
    auto installed=color.fragment;const auto before=installed.text;
    for(const auto source:{"void main(){gl_FragData[1+1]=vec4(1.0);}","void main(){int i=0;gl_FragData[i]=vec4(1.0);}","void main(){gl_FragData[8]=vec4(1.0);}","void main(){gl_FragData[01]=vec4(1.0);}","void main(){gl_FragData[\n0]=vec4(1.0);}","void main(){gl_FragColor=vec4(1.0);gl_FragData[0]=vec4(1.0);}","void main(){gl_FragColor=gl_Color;}","void main(){gl_FragColor=gl_TexCoord[0];}","void main(){gl_FragColor=vec4(mc_Entity.x);}","struct S{vec4 color;};\nvoid main(){gl_FragColor=vec4(1.0);}","varying vec2 uv[2];\nvoid main(){gl_FragColor=vec4(1.0);}","varying vec2 uv,other;\nvoid main(){gl_FragColor=vec4(1.0);}","attribute vec3 p;\nvoid main(){gl_FragColor=vec4(1.0);}","varying ivec2 uv;\nvoid main(){gl_FragColor=vec4(1.0);}","vec4 texture2D(sampler2D s,vec2 p){return vec4(0.0);}\nvoid main(){gl_FragColor=vec4(1.0);}","uniform float texture;\nuniform sampler2D s;\nvoid main(){gl_FragColor=texture2D(s,vec2(0.0));}","uniform float texture2D;\nvoid main(){gl_FragColor=vec4(1.0);}","void main(){gl_FragColor=textureCube(s,uv);}","void main(){float bloxdy_legacy_out0=1.0;gl_FragColor=vec4(1.0);}","void main(){vec4 gl_FragColor;gl_FragColor=vec4(1.0);}","void main(){gl_FragColor=(vec4(1.0);}","void helper(){}","void main(float x){}","void main(){}\nvoid main(){}","uniform float a;\nuniform float a;\nvoid main(){}"}){
        // Unresolved ordinary Minecraft identifiers are rejected below before
        // they could be mistaken for a provided native semantic input.
        requireCPU(fails([&]{installed=fragment(source);})&&installed.text==before,"Unsupported/ambiguous translation installed partial output.");
    }
    requireCPU(fails([&]{GlslTranslation::translate(prep("void main(){gl_Position=gl_Vertex;}"),PackShaderStage::Vertex);}),"Legacy vertex/matrix source fallback was invented.");
    const auto stageFiles=PackSources::create({{"v.vsh","#version 120\nvarying vec3 uv;\nvoid main(){uv=vec3(0.0);gl_Position=vec4(0.0);}"},{"f.fsh","#version 120\nvarying vec2 uv;\nvoid main(){gl_FragColor=vec4(uv,0.0,1.0);}"}});requireCPU(fails([&]{GlslTranslation::preparePair(*stageFiles,"v.vsh","f.fsh",{});}),"Mismatched pair varyings were accepted.");
    auto invalid=prep("void main(){}\n");invalid.version=330;requireCPU(fails([&]{GlslTranslation::translate(invalid,PackShaderStage::Vertex);}),"Unsupported source version was fabricated as 120.");
    invalid=prep("#extension all : warn\nvoid main(){}\n");requireCPU(fails([&]{GlslTranslation::translate(invalid,PackShaderStage::Vertex);}),"Extension capabilities were assumed by translation.");
    invalid=prep("void main(){}\n");invalid.text+="#define SPOOF 1\n";requireCPU(fails([&]{GlslTranslation::translate(invalid,PackShaderStage::Vertex);}),"Unresolved preprocessing was accepted by translation.");
    invalid=prep("void main(){}\n");invalid.text+="#line 1 99\n";requireCPU(fails([&]{GlslTranslation::translate(invalid,PackShaderStage::Vertex);}),"Translation source identity was fabricated.");
    std::string deep="void main(){";for(unsigned i=0;i<65;++i)deep+='(';deep+='1';for(unsigned i=0;i<65;++i)deep+=')';deep+=";}";requireCPU(fails([&]{fragment(deep);}),"Translation nesting limit failed.");
    invalid=prep("void main(){gl_FragColor=vec4(1.0);}");invalid.text.resize(8*1024*1024,' ');requireCPU(fails([&]{GlslTranslation::translate(invalid,PackShaderStage::Fragment);}),"Translated output growth bypassed 8 MiB limit.");invalid.text+=' ';requireCPU(fails([&]{GlslTranslation::translate(invalid,PackShaderStage::Fragment);}),"Translation input byte limit failed.");
    invalid=prep("void main(){}");for(unsigned i=0;i<131073;++i)invalid.text+="x ";requireCPU(fails([&]{GlslTranslation::translate(invalid,PackShaderStage::Fragment);}),"Translation token limit failed.");
    std::string many;for(unsigned i=0;i<257;++i)many+="uniform float x"+std::to_string(i)+";\n";many+="void main(){}";requireCPU(fails([&]{fragment(many);}),"Translation interface limit failed.");
}
